small = ParagraphStyle("small", parent=body, fontSize=7.2, leading=9)
mono = ParagraphStyle("mono", parent=body, fontName="Courier", fontSize=7.1, leading=9, backColor=colors.HexColor("#F1F5F7"), borderPadding=6)

def p(text, style=body): return Paragraph(text, style)
def table(rows, widths=None, header=True, fs=7.2):
    t = Table([[p(str(c), small) for c in row] for row in rows], colWidths=widths, repeatRows=1 if header else 0, hAlign="LEFT")
    cmds = [("VALIGN",(0,0),(-1,-1),"TOP"),("GRID",(0,0),(-1,-1),0.45,colors.HexColor("#A9BBC5")),("LEFTPADDING",(0,0),(-1,-1),4),("RIGHTPADDING",(0,0),(-1,-1),4),("TOPPADDING",(0,0),(-1,-1),3),("BOTTOMPADDING",(0,0),(-1,-1),3)]
    if header: cmds += [("BACKGROUND",(0,0),(-1,0),NAVY),("TEXTCOLOR",(0,0),(-1,0),colors.white)]
    for i in range(1 if header else 0, len(rows)):
        if i % 2 == 0: cmds.append(("BACKGROUND",(0,i),(-1,i),colors.HexColor("#F4F8FA")))
    t.setStyle(TableStyle(cmds)); return t

def box(text, color):
    t=Table([[p(text, body)]], colWidths=[176*mm]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),color),("BOX",(0,0),(-1,-1),0.7,NAVY),("LEFTPADDING",(0,0),(-1,-1),7),("RIGHTPADDING",(0,0),(-1,-1),7),("TOPPADDING",(0,0),(-1,-1),6),("BOTTOMPADDING",(0,0),(-1,-1),6)])); return t

def page_num(canvas, doc):
    canvas.saveState(); canvas.setFont("Helvetica",7); canvas.setFillColor(colors.grey)
    canvas.drawString(18*mm, 10*mm, "PROJECT DOMUS | Guia vigente 2026-09-10")
    canvas.drawRightString(198*mm, 10*mm, f"Pagina {doc.page}"); canvas.restoreState()

