S += [PageBreak(), p("1. Mapa casi terminado con lo que ya tienes",h1), p("Todas las tierras del banco se unen a GND del ESP32. El ESP32 se alimenta por USB. No conectar otra fuente positiva al mismo tiempo."), p("ESP32-S3 N16R8 (USB)<br/>|-- 3V3: LCD VCC, DHT11, suelo, nivel, LDR, PIR, HX1838<br/>|-- GND: retorno comun de todos los anteriores y controles<br/>|-- GPIO21 SDA + GPIO13 SCL: LCD I2C, solo cuatro cables<br/>|-- GPIO1 suelo AO | GPIO2 nivel S | GPIO3 divisor LDR<br/>|-- GPIO9 PIR OUT | GPIO14 DHT DATA | GPIO12 HX1838 OUT<br/>|-- GPIO10 STOP->GND | GPIO11 MUTE->GND<br/>|-- GPIO5 LED sala | GPIO6 LED dormitorio<br/>|-- GPIO8 -> S8050 -> tres LED cultivo<br/>`-- GPIO15 -> segundo S8050 -> buzzer activo 5 V (o buzzer pasivo solo como alternativa)",mono), box("Bomba, ventilador, rele desnudo y transistor sin marca se prueban por separado. No forman parte de este bus simultaneo.",AMBER), p("Mapa final despues de comprar",h2), p("Fuente cerrada 5 V/5 A -> fusible lento 4 A -> switch maestro -> bus 5 V. Del bus salen ramales al ESP32, DRV8833, MAX98357A y cargas. GND comun. El DRV8833 maneja bomba y ventilador; no se compran reles." )]
S += [PageBreak(), p("2. Tabla maestra de pines",h1), table([["GPIO","Conexion exacta","Modo"],["1","AO sensor de suelo","ADC"],["2","S sensor de nivel","ADC"],["3","Nodo LDR + resistor 10 k a GND","ADC"],["4","DRV AIN1 (solo final)","Salida"],["5","LED sala: GPIO-resistor 330-anodo; catodo-GND","Salida"],["6","LED dormitorio: igual","Salida"],["7","DRV BIN1 (solo final)","Salida"],["8","Resistor 1 k a base S8050 cultivo","Salida"],["9","OUT PIR","Entrada"],["10","Boton STOP normalmente abierto a GND","INPUT_PULLUP"],["11","Boton MUTE normalmente abierto a GND","INPUT_PULLUP"],["12","OUT receptor IR HX1838","Entrada"],["13","SCL LCD I2C","I2C"],["14","DATA DHT11","Digital"],["15","1 k a base S8050 de buzzer","Salida"],["16","BCLK MAX98357A (final)","I2S"],["17","LRC MAX98357A (final)","I2S"],["18","DIN MAX98357A (final)","I2S"],["21","SDA LCD I2C","I2C"]],[20*mm,118*mm,35*mm]), p("Pines reservados 4, 7, 16, 17 y 18 se mantienen sin carga en el esqueleto actual. Confirmar siempre la serigrafia de la placa real.",small)]
S += [PageBreak(), p("3. Sensores y LCD: conexion exacta",h1), table([["Pieza","VCC","GND","Senal"],["LCD1602 + backpack I2C","3V3","GND","SDA->21, SCL->13"],["DHT11 modulo","3V3","GND","DATA/S->14"],["Suelo resistivo","3V3","GND","AO->1; DO libre"],["Nivel de agua","3V3","GND","S/AO->2"],["PIR","3V3","GND","OUT->9"],["HX1838","3V3","GND","OUT/S->12"]],[47*mm,28*mm,28*mm,73*mm]), p("LDR en divisor",h2), p("3V3 -> LDR -> NODO -> resistor 10 kOhm -> GND. NODO -> GPIO3. Si el valor cambia al reves de lo esperado, se corrige la comparacion del firmware; no se sube el ADC a 5 V."), box("El LCD observado funciona a 3.3 V: usar solamente GND, VCC, SDA y SCL. No conectar ademas los 16 pines paralelos. Ajustar el potenciometro del backpack si hay luz pero no caracteres.",GREEN), p("DHT11 suelto",h2), p("Mirando la rejilla frontal, el orden usual es VCC, DATA, NC, GND, pero los modulos de tres pines pueden variar. Leer la serigrafia. Un sensor suelto requiere pull-up de 10 kOhm entre DATA y 3V3."), p("Sensores analogicos",h2), p("Calibrar con lecturas reales. Registrar suelo seco/humedo, nivel vacio/seguro y LDR cubierto/iluminado. Nunca aceptar 0 o 4095 fijo como lectura valida sin diagnostico." )]
S += [PageBreak(), p("4. Luces, transistores, diodos y buzzer",h1), p("LED directos de sala/dormitorio",h2), p("GPIO5 o GPIO6 -> resistor 330 Ohm -> anodo (pata larga). Catodo (pata corta y lado plano) -> GND. Un resistor por LED."), p("Tres LED de cultivo con S8050",h2), p("+5 V -> un resistor 330 Ohm por LED -> anodo de cada LED. Los tres catodos -> colector C del S8050. Emisor E -> GND. GPIO8 -> resistor 1 kOhm -> base B. Base -> resistor 10 kOhm -> GND. Antes de soldar, identificar E/B/C del ejemplar real; el encapsulado no garantiza el orden."), p("Buzzer activo TMB12A05",h2), p("+5 V -> positivo del buzzer. Negativo -> colector del segundo S8050. Emisor -> GND. GPIO15 -> 1 kOhm -> base; base -> 10 kOhm -> GND. El buzzer pasivo se prueba como alternativa y no se conecta simultaneamente."), p("Diodos",h2), table([["Uso","Orientacion"],["Motor DC o bomba","En paralelo con motor: catodo/raya al lado positivo, anodo al negativo"],["Bobina de rele suelta (solo prueba)","En paralelo con bobina: catodo/raya a positivo"],["LED","Anodo largo hacia positivo; catodo corto/lado plano hacia GND"]],[52*mm,124*mm]), box("Un diodo instalado al reves sobre la alimentacion produce un corto. Desconectar de inmediato si se calienta.",RED)]
