S += [PageBreak(), p("7. Montaje final despues de las compras",h1), p("Potencia",h2), p("Toma AC -> adaptador cerrado 5 V/5 A -> jack a tornillos -> fusible lento 4 A -> switch maestro DC -> BUS 5V. Distribuir +5 V y GND por borneras. Colocar 1000 uF cerca del DRV8833 y otro cerca del MAX98357A, respetando polaridad."), p("DRV8833",h2), p("VM->5V, GND->GND, nSLEEP->3V3. AIN1->GPIO4 y AIN2->GND; bomba entre AOUT1/AOUT2. BIN1->GPIO7 y BIN2->GND; ventilador entre BOUT1/BOUT2. Confirmar nombres del modulo exacto: algunos clones invierten el orden o exponen FAULT."), p("Audio",h2), p("MAX98357A VIN->5V, GND->GND, BCLK->GPIO16, LRC/WS->GPIO17, DIN->GPIO18. Parlante de 4 Ohm/3 W solamente entre SPK+ y SPK-; ninguno a GND."), box("Antes de unir el ESP32: fuente sola, polaridad correcta, 5 V medidos, fusible y switch probados. Alimentar el ESP32 por una sola ruta positiva. Todos los GND deben ser comunes.",RED), p("Compras pendientes",h2), p("DRV8833, fuente cerrada 5 V/5 A con adaptador, MAX98357A, parlante, baquelita, borneras, portafusible, dos fusibles lentos 4 A y cinco capacitores 1000 uF/25 V/105 C. No comprar INMP441, reles adicionales ni sensor UV." )]
S += [PageBreak(), p("8. Que firmware usar en cada etapa",h1), table([["Firmware","Hardware","Proposito"],["domus_selftest","ESP32 solo por USB","Arranque, serial, memoria y estabilidad"],["domus_esqueleto","Sensores + LCD, salidas fisicas bloqueadas","Lecturas, calibracion y fallos seguros"],["domus_ir_learn","HX1838 + control","Registrar los 21 codigos reales"],["domus_actuator_test","Fuente + DRV + una carga cada vez","Direccion, PWM, timeout y paro"],["domus_audio_test","MAX98357A + parlante","Tono y frases desde flash"],["casa_inteligente_v4","Todo aprobado","Automatizacion final + IR + audio"]],[42*mm,65*mm,69*mm]), p("El esqueleto no se convierte en final cambiando un solo false. El final debe implementar perfiles, arranque OFF, nivel minimo, timeout de bomba, rearmado manual, histéresis, horario de cultivo, watchdog y rechazo de sensores invalidos."), p("Orden de desarrollo",h2), p("1) congelar mapa GPIO; 2) calibrar entradas; 3) aprender IR; 4) probar DRV; 5) probar audio; 6) integrar control manual; 7) integrar automatico; 8) prueba de una hora; 9) congelar firmware de feria."), p("Fuente de verdad",h2), p("Consultar la nota Obsidian '44 - Arquitectura y ciclo de vida del firmware'. El HTML interactivo sirve como plano navegable; esta guia es la copia imprimible." )]
